#!/usr/bin/env node
/**
 * Create a local `.env` from `.env.example` with development-safe values (OPS-70): loopback
 * binds, explicit list origins, and cryptographically random secrets that exist only on this
 * machine. The template itself keeps placeholders only (documentation gate check 7), and the
 * services reject placeholders at startup (OPS-53) — this script is the documented bridge
 * between the two, replacing the bare `cp` step in docs/development/01-development-environment.md §4.
 *
 * Dependency-free cross-platform Node (GOV-45). Refuses to overwrite an existing `.env`
 * unless `--force` is passed. An unknown placeholder fails loudly so this table and
 * `.env.example` cannot drift apart silently.
 */
import { randomBytes } from 'node:crypto';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const EXAMPLE_PATH = join(ROOT, '.env.example');
const ENV_PATH = join(ROOT, '.env');

const force = process.argv.includes('--force');
if (existsSync(ENV_PATH) && !force) {
  process.stderr.write('.env already exists; refusing to overwrite (pass --force to regenerate).\n');
  process.exit(1);
}

const generated = {
  postgresPassword: randomBytes(16).toString('hex'),
  coreDbPassword: randomBytes(16).toString('hex'),
  relationDbPassword: randomBytes(16).toString('hex'),
  sosDbPassword: randomBytes(16).toString('hex'),
  secret: () => randomBytes(32).toString('hex'),
};

/**
 * Explicit development values. Everything not listed here follows the generic placeholder rules
 * below; a placeholder that matches neither fails the script (drift protection).
 */
const TABLE = {
  NODE_ENV: 'development',
  LOG_LEVEL: 'info',
  SERVICE_NAME: 'api',
  // Safe binds for a development machine: loopback only (OPS-70). Compose overrides these to
  // 0.0.0.0 inside the container network, where they are not reachable from outside the host.
  API_HOST: '127.0.0.1',
  METRICS_HOST: '127.0.0.1',
  WEB_HOST: '127.0.0.1',
  WEB_ORIGIN: 'http://localhost:5173',
  CORS_ALLOWED_ORIGINS: 'http://localhost:5173,http://localhost:8080',
  TRUST_PROXY: 'false',
  DATABASE_URL: `postgres://boro_core:${generated.coreDbPassword}@localhost:5432/boro_biya`,
  DB_ADMIN_URL: `postgres://boro_biya:${generated.postgresPassword}@localhost:5432/boro_biya`,
  POSTGRES_USER: 'boro_biya',
  POSTGRES_PASSWORD: generated.postgresPassword,
  POSTGRES_DB: 'boro_biya',
  CORE_DB_PASSWORD: generated.coreDbPassword,
  RELATION_DB_PASSWORD: generated.relationDbPassword,
  SOS_DB_PASSWORD: generated.sosDbPassword,
  S3_ACCESS_KEY_ID: 'unused-in-development',
  S3_SECRET_ACCESS_KEY: generated.secret(),
  S3_BUCKET: 'boro-biya-uploads',
  API_ORIGIN: 'http://localhost:3000',
  GEOCODING_PROVIDER: 'none',
  GEOCODING_API_KEY: 'unused-in-development',
  ROUTING_PROVIDER: 'none',
  ROUTING_API_KEY: 'unused-in-development',
  PUSH_PROVIDER: 'none',
  PUSH_SERVER_KEY: 'unused-in-development',
  VITE_API_BASE: '',
  VITE_DEFAULT_LOCALE: 'en',
  BUILD_COMMIT: 'dev',
};

function valueFor(variable, placeholder) {
  const inner = placeholder.slice(1, -1);
  if (Object.hasOwn(TABLE, variable)) return TABLE[variable];
  if (inner === 'generate-a-random-32-byte-value') return generated.secret();
  if (/^(true|false)$/.test(inner)) return inner;
  if (/^\d+$/.test(inner)) return inner;
  if (inner.includes('|')) {
    const first = inner.split('|')[0];
    if (first !== undefined && /^[a-z0-9]+$/.test(first)) return first;
  }
  if (/^https?:\/\/[^\s>]+\.invalid[^\s>]*$/.test(inner)) return inner;
  if (inner.startsWith('./') || inner.startsWith('../')) return inner;
  throw new Error(
    `no development value known for ${variable} (placeholder "${placeholder}"); add it to the table in scripts/env/create.mjs`,
  );
}

const template = readFileSync(EXAMPLE_PATH, 'utf8');
const outputLines = [
  '# Generated by `bun run env:create` — development values only.',
  '# Secrets below were generated on this machine and exist nowhere else; never commit or share this file.',
  '# Descriptions of every variable live in .env.example (OPS-68).',
];

for (const rawLine of template.replace(/\r\n/g, '\n').split('\n')) {
  const line = rawLine.trimEnd();
  const match = /^([A-Z][A-Z0-9_]*)=(<[^>]+>)$/.exec(line.trim());
  if (match === null) {
    // Keep comments and structure so the generated file stays readable next to the template.
    if (line.trim() !== '' && !line.trimStart().startsWith('#')) {
      throw new Error(`.env.example line is not a comment or KEY=<placeholder>: ${line.slice(0, 60)}`);
    }
    outputLines.push(line);
    continue;
  }
  const [, variable, placeholder] = match;
  outputLines.push(`${variable}=${valueFor(variable, placeholder ?? '')}`);
}

writeFileSync(ENV_PATH, `${outputLines.join('\n')}\n`, 'utf8');
process.stdout.write(
  `.env created with development-safe values (loopback binds, generated secrets).\n` +
    `Next: docker compose up -d db   then   bun run db:migrate   then   bun run dev\n`,
);
